import{_ as a,H as t,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"02 | 知识过程中的认知模式","description":"","frontmatter":{},"headers":[{"level":2,"title":"与知识消费有关认知行为模式","slug":"与知识消费有关认知行为模式","link":"#与知识消费有关认知行为模式","children":[]},{"level":2,"title":"清晰模式——最高效的知识消费模式","slug":"清晰模式——最高效的知识消费模式","link":"#清晰模式——最高效的知识消费模式","children":[]},{"level":2,"title":"庞杂模式——不可言说知识的消费","slug":"庞杂模式——不可言说知识的消费","link":"#庞杂模式——不可言说知识的消费","children":[]},{"level":2,"title":"复杂模式与知识学习","slug":"复杂模式与知识学习","link":"#复杂模式与知识学习","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·AI时代的软件工程/02｜知识过程中的认知模式.md","filePath":"徐昊·AI时代的软件工程/02｜知识过程中的认知模式.md","lastUpdated":1795556403000}'),p={name:"徐昊·AI时代的软件工程/02｜知识过程中的认知模式.md"};function l(s,e,r,o,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_02-知识过程中的认知模式" tabindex="-1">02 | 知识过程中的认知模式 <a class="header-anchor" href="#_02-知识过程中的认知模式" aria-label="Permalink to &quot;02 | 知识过程中的认知模式&quot;">​</a></h1><p>你好，我是徐昊，今天我们来继续学习 AI 时代的软件工程。</p><p>上节课，我们了解到不可言说知识需要从经验中获取，很难通过语言或其他形式传播。想要把任何工作转化为知识工程，都需要识别其中关键的不可言说知识，并构造出知识传递效率更高的流程。</p><p>那我们怎么才能评估知识传递是否高效呢？关键就是知识传递和消费的效率。而知识在传递和消费的过程中，会在知识的消费者身上产生不同的认知模式。通过认知行为模式，我们可以进一步理解知识传递和消费的效率。</p><p>今天我们就来学习知识是如何被消费和传递的，以及在知识被消费和传递的过程中，会对应哪些认知行为模式。</p><h2 id="与知识消费有关认知行为模式" tabindex="-1">与知识消费有关认知行为模式 <a class="header-anchor" href="#与知识消费有关认知行为模式" aria-label="Permalink to &quot;与知识消费有关认知行为模式&quot;">​</a></h2><p>所谓认知模式，就是指人利用知识进行决策时，采取的行为模式。我们可以使用 Cynefin 框架理解不同知识消费和传递中产生的不同认知行为模式。</p><p>Cynefin 框架是戴维·斯诺登（David J. Snowden）在 1999 年围绕知识管理和组织战略开发的一个框架。Cynefin 框架原本是一种解决问题的工具，它可以帮助我们将各种情况归入由因果关系定义的五个“领域”。</p><p>根据 2020 版 Cynefin 框架的定义，这五个领域分别是：清晰（Clear）、庞杂（Complicated）、复杂（Complex）、混乱（Chaotic）和困惑（Aporetic/Confused）。利用这五个领域，可以帮助我们更准确地评估情况，并做出适当的反应。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/02/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/02/1.png" alt=""></a></p><ul><li>Cynefin 框架</li></ul><p>限定在知识管理与知识传递的场景里，Cynefin 框架的不同领域，实际对应了我们传递和消费不同类型知识时的认知行为模式。这五种不同的认知行为模式，其认知水平由高到低分别是：清晰、庞杂、复杂、混乱和困惑。</p><p>这五种行为模式中，困惑（Aporectic/Confused）与其他四个不同，表示我们无法理解要解决的问题，因而当处在该模式时我们不能进行任何有效处理，是最低的认知水平。除困惑以外，处在其他四种认知模式时，我们都需要对问题进行诊断，并采取相应的行动，只是诊断与解决问题的方式不同而已。下面我们来讲解一下，这四种行为模式的特点。</p><h2 id="清晰模式——最高效的知识消费模式" tabindex="-1">清晰模式——最高效的知识消费模式 <a class="header-anchor" href="#清晰模式——最高效的知识消费模式" aria-label="Permalink to &quot;清晰模式——最高效的知识消费模式&quot;">​</a></h2><p>首先是清晰（Clear）的认知行为模式。这种行为模式也被称作已知（Known）或显然（Obvious）模式。当处于清晰模式时，要解决的问题是稳定且具有清晰的因果关系。每个人都能轻易辨别，正确答案往往不言自明，无可争议。</p><p>处在清晰模式时，认知行为表现为：感知（sense）- 归类（categorize）- 响应（Respond）。</p><p>也就是说，对于某一个问题，首先感知它是什么问题，然后将这个问题归类为已经知晓的某个解决方案中，并使用这个解决方案进行响应。</p><p>比如你去银行，业务员会首先询问你需求，这是感知。在明确了你需求之后，业务员会将你的需求归类为银行的某项业务，比如是汇款啊，购汇啊，还是开户、销户。接着业务员就会使用对应业务流程来响应你的需求，会让你填写对应的表格，比如汇款单、开户申请之类，然后为你办理业务。</p><p>在这个过程中，对于问题的定义是已知的，解决方案是已知的，问题与解决方案的对应关系也是已知的。因而在认知上无负担，是认知水平最高的行为模式。所以清晰模式也叫“已知的已知”，此时如何决策是不容置疑的，因为各方都有共识。</p><p>在清晰模式“感知 - 归类 - 响应”的行为模式中，我们应用了哪些知识呢？</p><p>对于问题的感知，通常是不可言说知识。定义问题永远比解决问题困难。但是因为在清晰模式下，是已知的已知，且每个人都能轻易辨别。那么我们使用的知识要么是显式知识，要么是已经充分掌握的不可言说知识。比如在银行的例子里，客户可能会说，我要交学费，我要报名参加一个比赛，业务员都能瞬间明白，客户真正的问题是要汇款。</p><p>对于归类，也就是找到对应的已知解决方案，使用的是显式知识。而响应，也就是做出正确的处理，理论上说应该是不可言说，但因为在清晰模式下，所以要么是显式知识，要么是已经充分掌握的不可言说知识。同样，在银行的例子中，汇款对应了汇款流程，这是显式知识。去执行汇款流程的确需要一定的经验，但又没那么复杂，同样是显式知识或已经充分掌握的不可言说知识。</p><p>因而，在清晰模式下，消费的知识是显式知识和已经充分掌握了的不可言说知识。</p><h2 id="庞杂模式——不可言说知识的消费" tabindex="-1">庞杂模式——不可言说知识的消费 <a class="header-anchor" href="#庞杂模式——不可言说知识的消费" aria-label="Permalink to &quot;庞杂模式——不可言说知识的消费&quot;">​</a></h2><p>庞杂（Complicated）的认知行为模式也叫专家模式。庞杂模式与清晰模式不同，它可能包含多个正确答案，尽管因果之间存在明确的关系，但并非每个人都能看清。当处在庞杂模式时，对于要解决的问题，解决方法目前并不明确，在寻找解决方案的过程中，经验与分析能力发挥关键作用。这种方法并不容易，往往需要专业知识。因而被称作专家模式。</p><p>在庞杂模式下，认知行为表现是感知（sense）- 分析（Analysis）- 响应（Respond）。</p><p>对于某一个问题，首先感知它是什么问题，然后通过分析寻找可能的解决方案，并使用这个解决方案进行响应。</p><p>比如你去医院，如果是常见病症，那么医生是知道怎么处理的。医生会通过各种检查感知你实际的状态，但并不能根据这些检查结果直接确定治疗方案。毕竟不同的疾病可能有相似的病症。医生需要通过分析具体是什么病因，并综合你的状态、过敏史等情况，才能确定治疗方案（响应）。</p><p>在这个过程中，问题是已知的，解决方案是已知的多种选择，问题与解决方案的对应关系是未知的。庞杂模式是“已知未知”的领域，庞杂模式比起清晰模式具有更大的认知负载，因而认知效率是低于清晰模式的。</p><p>在庞杂模式“感知 - 分析 - 响应”的行为模式中，我们应用了哪些知识呢？庞杂模式与清晰模式非常类似，唯一的不同在于对于解决方案的寻找，也就是分析这一行为，这依赖于专业知识与能力，是典型的不可言说知识。这也是庞杂模式效率低于清晰模式的根因。</p><p>清晰与庞杂模式也被称作有序模式，是知识在消费和应用中产生的认知行为模式。清晰模式自不必多言，在庞杂模式中，虽然是由专家的不可言说知识提供了关键的分析能力，但这部分不可言说知识是已经被掌握和学习了的，并不存在知识的学习、获取与传递。一旦需要学习新的知识，那么就将进入到无序模式中。</p><h2 id="复杂模式与知识学习" tabindex="-1">复杂模式与知识学习 <a class="header-anchor" href="#复杂模式与知识学习" aria-label="Permalink to &quot;复杂模式与知识学习&quot;">​</a></h2><p>无论清晰模式还是庞杂模式，在开始响应之前，我们至少明确知道存在一个正确答案。然而，在复杂模式（Complex）下，正确答案是无法提前预知的，只能通过反思理解真正的问题和解决方案是什么，无论在前期多么的努力，都无法提前感知。</p><p>复杂认知行为模式是反思模式，它表现为：探测（Probe）- 感知（Sense）- 响应（Respond）。只能通过探测收集必要的信息，再通过反思感知，最后采取必要响应，调整之前的方案。</p><p>一个典型的例子是创业或产品创新，无论在前期做多少准备，也无法确保一定会成功，就算成功也无法保证成功的方式和所构想的方式就是一致的。只能通过不停地感知，做出调整。</p><p>当处在复杂模式时，对于要解决的问题，并不知晓是否能够解决。无论前期做多少准备，都不能确保存在解决方案，而是需要依赖反思改进。因此复杂模式也被称作“未知的未知数”。</p><p>复杂模式的认知负载远远高于前面介绍的两种模式。首要原因在于其中问题的本质和解决方案都不是一开始就清晰可见的。在这种模式下，我们不能仅依赖于预设的规则或经验，而是必须不断地探索和适应，这本身就是一个学习过程。</p><p>复杂模式是不可言说知识在传递和学习时，主要依据的一个认知行为模式。探测 - 感知本身就是一种启动 - 反馈循环，是一种社会化的学习活动。</p><p>最后是混乱模式，某种程度上说，这是个反模式。它表现为：行动（Act）- 感知（Sense）-响应（Respond）。混乱模式的主要目的是通过快速行动重新建立秩序，尽快回到前面三种模式当中。因而混乱模式不是基于知识的反应，而是应激式的反应，我们在这里不做过多的讨论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我们介绍了如何通过 Cynefin 框架理解不同知识消费和传递中产生的不同认知行为模式。其中对于知识过程有重要意义的是三个模式，产生于知识消费的清晰与庞杂模式，产生于知识学习的复杂模式。</p><p>我在文稿里画了一张表，总结了这五种模式的表现、例子和对应的知识活动，你可以打开文稿看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/02/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/02/2.jpeg" alt=""></a></p><p>需要说明的一点是，这五种模式是不同的行为模式，而不是对于问题的划分。借助 Cynefin 框架，主要帮助我们理解对于同样的问题，人们有什么样的响应方式，而不是对问题本身的划分。比如，对于轮扁的学生，他们只能使用复杂模式应对削车轮这个问题，而对于轮扁自己，他可以使用庞杂模式处理。问题不变，但是不同的人群有不同的认知模式。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请思考软件开发过程中，有哪些典型的认知行为模式。</p><p>欢迎在留言区分享你的想法，我会让编辑置顶一些优质回答供大家学习讨论。</p>',47)])])}const u=a(p,[["render",l]]);export{B as __pageData,u as default};
